from itertools import combinations
from typing import List

def find_minimum_stands(N: int, M: int, stands: List[str]) -> int:
    flavors_of_stands = []
    for stand in stands:
        s = int("".join(list(map(lambda x: '1' if x == 'o' else '0', stand))), base=2)
        flavors_of_stands.append(s)
    total = 2 ** M - 1
    for i in range(1, N + 1):  # Corrected the range to include N
        all_cases = combinations(range(N), i)
        for case in all_cases:
            cur_ans = 0
            for idx in case:
                cur_ans |= flavors_of_stands[idx]
            if cur_ans == total:
                return len(case)
    return N  # In case no combination covers all flavors
